style:
.wwu-link{transition:background 150ms ease,transform 150ms ease}
.wwu-link:hover{background:#fff !important;transform:translateX(3px)}
@media (max-width:760px){.vtf-grid{grid-template-columns:1fr !important}.vtf-grid>div{grid-column:auto !important;grid-row:auto !important}}
.fw-spin g{transform-origin:24px 24px;transform-box:view-box;animation:fwspin 6s linear infinite}
@keyframes fwspin{to{transform:rotate(360deg)}}
@media (prefers-reduced-motion:reduce){.fw-spin g{animation:none}}
.pc-bar{transition:filter 150ms ease}.pc-bar:hover{filter:brightness(1.08)}
.fw-spiral{transform-origin:230px 165px;transform-box:view-box;animation:fwspin 14s linear infinite reverse}
@media (prefers-reduced-motion:reduce){.fw-spiral{animation:none}}

/* narrow screens: the model stacks vertically and the flywheel sits under its text */
@media (max-width: 900px) {
  .am-scroll { overflow: visible !important; }
  .am-grid { min-width: 0 !important; display: flex !important; flex-direction: column; gap: 12px !important; }
  .am-grid > * { grid-column: auto !important; grid-row: auto !important; }
  .am-scale, .am-label { display: none !important; }
  .am-stage { display: flex !important; flex-direction: column; gap: 10px; }
  .am-stage > *, .am-stage > * > * { margin-left: 0 !important; clip-path: none !important; border-radius: 14px !important; }
  .am-stage > div { padding: 14px 16px !important; }
  .am-stage > div:nth-child(3) { padding: 0 !important; }
  .am-stage > div:nth-child(3) > div { padding: 12px 16px !important; }
  .am-stage { gap: 26px !important; }
  .am-stage > div { position: relative; overflow: visible !important; }
  .am-stage > div + div::before { content: "\2193"; position: absolute; left: 50%; top: -23px; transform: translateX(-50%); color: var(--artblue); font-weight: 700; font-size: 16px; line-height: 1; }
  .am-stage > div:last-child { min-height: 110px; }
  .pc-bar { flex-direction: column; align-items: flex-start !important; border-radius: 16px !important; }
  .ateam { grid-template-columns: 1fr !important; }
}
